// Generated from a stock PostgreSQL 18.3 server's pg_settings (scratch generator, not shipped).
// Each row: [name, vartype, context, unit, default setting, boot_val, category, short_desc, ...range, source].
// Integer and real rows carry [min, max]; enum rows carry their enumvals; string and bool rows carry null.
// Defaults are the server's, except where the engine differs: the C locale, the UTC time zone, port
// 5432, and no TCP keepalive (the engine serves no socket of its own). File paths are left out.
// Two descriptions end in "process" plus a full stop. That literal trips the bundle portability check for
// Node's `process` global, so `sentence` adds the stop at run time.
const sentence = (text: string): string => `${text}.`;

